<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { ShieldCheck, Clipboard, Keyboard, PanelsTopLeft, Mic, Mouse, ChevronRight } from 'lucide-vue-next'
import { backend,errorMessage } from '../services/backend'
const props=defineProps<{snapshot:Record<string,any>|null}>()
const emit=defineEmits<{navigate:[page:string]}>()
const step=ref(0),selected=ref('clipboard'),busy=ref(false),error=ref('')
const features=[{id:'clipboard',title:'剪贴板同步',icon:Clipboard,detail:'在一台 Mac 复制，另一台直接粘贴。文字、图片和文件都会同步。'},{id:'input',title:'键鼠共享',icon:Keyboard,detail:'一套键盘和鼠标穿过屏幕边缘，控制同一网络里的其他 Mac。需要辅助功能权限。'},{id:'remote_applications',title:'远程应用',icon:PanelsTopLeft,detail:'把另一台 Mac 上的应用窗口，直接打开在这台 Mac 上。需要屏幕录制权限。',beta:true},{id:'microphone',title:'麦克风共享',icon:Mic,detail:'把另一台 Mac 或 iPhone 的麦克风，作为这台 Mac 的输入设备。开启后还需选择音源。',beta:true},{id:'mouse',title:'鼠标自定义',icon:Mouse,detail:'把鼠标侧键映射成快捷键、窗口切换或系统操作。需要输入监控权限。',beta:true}]
const enabled=ref<Record<string,boolean>>({})
watch(()=>props.snapshot?.features,(value)=>{if(value&&Object.keys(enabled.value).length===0)enabled.value={...value}},{immediate:true})
const permissions=computed<any[]>(()=>props.snapshot?.permissions?.items??[])
const preview=computed(()=>features.find(f=>f.id===selected.value)!)
async function authorize(id:string){error.value='';try{await backend.invoke('permissions.open',{permission:id,mode:'authorize'})}catch(e){error.value=errorMessage(e)}}
async function complete(){busy.value=true;error.value='';try{await backend.invoke('onboarding.complete',{features:enabled.value});emit('navigate','devices')}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
</script>
<template><section class="onboarding"><header><h1>{{step===0?'先让 DeskFuse 获得必要的访问权限':'选择要开启的功能'}}</h1><p>{{step===0?'这些权限由 macOS 管理，只在本机使用；随时可以在系统设置或应用中更改。':'完成设置后，可在「设置 › 通用」中随时修改。'}}</p></header><div v-if="error" class="notice" role="alert">{{error}}</div><div v-if="step===0" class="permissions"><h3>必要权限</h3><div v-for="permission in permissions" :key="permission.id" class="permission card"><ShieldCheck :size="22"/><div><h2>{{permission.title}}</h2><p>{{permission.purpose}}</p></div><button class="button" :disabled="permission.granted" @click="authorize(permission.id)">{{permission.granted?'已授权':'授权'}}</button></div><p v-if="!permissions.length" class="notice">原生服务未连接，暂时无法读取系统权限。</p><small>权限只在本机使用。DeskFuse 不会上传你的剪贴板内容、屏幕画面或音频。</small></div><div v-else class="feature-selection"><div><button v-for="feature in features" :key="feature.id" class="feature-row" :class="{selected:selected===feature.id}" @click="selected=feature.id"><component :is="feature.icon" :size="16"/><span>{{feature.title}}</span><span v-if="feature.beta" class="badge beta">Beta</span><input v-model="enabled[feature.id]" type="checkbox" class="toggle" :aria-label="feature.title" :disabled="!snapshot" @click.stop/></button></div><div class="preview"><component :is="preview.icon" :size="60"/><h2>{{preview.title}}</h2><p>{{preview.detail}}</p></div></div><footer><span>{{step===0?'系统权限':'功能选择'}} · {{step+1}} / 2</span><div class="spacer"/><button v-if="step" class="button" :disabled="busy" @click="step=0">上一步</button><button v-if="step===0" class="button primary" @click="step=1">继续<ChevronRight :size="14"/></button><button v-else class="button primary" :disabled="busy||!snapshot" @click="complete">{{busy?'正在保存…':'完成设置'}}</button></footer></section></template>
<style scoped>.onboarding{display:flex;flex-direction:column;gap:24px;max-width:880px;width:100%;padding:24px;margin:0 auto;height:100%;overflow:auto}header p{color:var(--secondary);margin-top:12px}.permissions{display:flex;flex-direction:column;gap:12px;flex:1}.permission{display:flex;align-items:center;gap:16px}.permission>div{flex:1}.permission p{font-size:12px;color:var(--secondary);margin-top:6px}.feature-selection{display:grid;grid-template-columns:300px 1fr;gap:24px;flex:1}.feature-row{display:flex;gap:12px;align-items:center;width:100%;padding:12px;border-radius:8px;height:44px}.feature-row.selected{background:color-mix(in srgb,var(--accent) 18%,transparent)}.feature-row>span:first-of-type{flex:1;text-align:left}.preview{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:20px;text-align:center;padding:24px}.preview>svg{color:var(--accent)}.preview p{color:var(--secondary);max-width:300px}footer{display:flex;align-items:center;gap:8px;padding-top:16px;border-top:1px solid var(--line)}footer>span{color:var(--secondary);font-size:12px}</style>
